<script setup>
import {ref,onMounted,computed,inject} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,api} from '../api/client';import StatusBadge from '../components/StatusBadge.vue';import CursorPager from '../components/CursorPager.vue';import ArchiveDialog from '../components/ArchiveDialog.vue';import DocumentBatchDialog from '../components/DocumentBatchDialog.vue';import {Upload,FileText,ArrowUpRight,Play,Download,RefreshCw,Search,Trash2,RotateCcw,Plus,X,FolderOpen} from 'lucide-vue-next';
const route=useRoute(),router=useRouter(),user=inject('user');const data=ref({items:[]}),doc=ref(null),rev=ref(null),error=ref(''),busy=ref(false),loading=ref(false),file=ref(null),title=ref(''),query=ref(''),archived=ref(false),confirm=ref(null),notice=ref(null),showUpload=ref(false),dragging=ref(false);
const selectedRows=ref({}),batchConfirm=ref(null),batchResult=ref(null),selecting=ref(false);
const selectedCount=computed(()=>Object.keys(selectedRows.value).length),allSelected=computed(()=>data.value.items.length>0&&data.value.items.every(d=>selectedRows.value[d.id])),someSelected=computed(()=>data.value.items.some(d=>selectedRows.value[d.id]));
function toggleRow(d,checked){if(checked)selectedRows.value[d.id]={id:d.id,title:d.title,archive_version:d.archive_version,archived:d.archived};else delete selectedRows.value[d.id]}
function togglePage(checked){for(const d of data.value.items)toggleRow(d,checked)}
async function selectAllMatches(){selecting.value=true;error.value='';try{const response=await get('/document-selections?'+new URLSearchParams({q:query.value,archived:String(archived.value)}));selectedRows.value=Object.fromEntries(response.items.map(d=>[d.id,d]))}catch(e){error.value=e.message}finally{selecting.value=false}}
function batchAction(action,items){batchConfirm.value={action,items:items||Object.values(selectedRows.value)}}
async function batchCompleted(result){const titles=Object.fromEntries(batchConfirm.value.items.map(d=>[d.id,d.title]));batchResult.value={...result,failures:result.failures.map(f=>({...f,title:titles[f.id]}))};batchConfirm.value=null;selectedRows.value={};await load()}
const canReview=computed(()=>user.value.roles.some(x=>['admin','reviewer'].includes(x)));const canOperate=computed(()=>user.value.roles.some(x=>['admin','operator'].includes(x)));
async function load(cursor=''){error.value='';loading.value=true;if(!cursor)selectedRows.value={};try{if(route.params.id){doc.value=await get('/documents/'+route.params.id);rev.value=await get('/document-revisions/'+doc.value.latest_revision_id)}else data.value=await get('/documents?'+new URLSearchParams({q:query.value,archived:String(archived.value),...(cursor?{cursor}:{})}))}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(()=>load());
async function upload(){if(!file.value)return;busy.value=true;error.value='';try{const form=new FormData();form.append('title',title.value||file.value.name);form.append('file',file.value);const {data:r}=await api('/documents/import',{method:'POST',body:form});router.push(r.analysis_job?'/jobs/'+r.analysis_job.id:'/documents/'+r.document.id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function analyze(){busy.value=true;error.value='';try{const {data:j}=await api('/analysis-runs',{method:'POST',body:{document_revision_id:rev.value.id,workflow_profile:'auto'}});router.push('/jobs/'+j.id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function openTable(assetId){busy.value=true;try{const r=await api('/price-workbooks',{method:'POST',body:{document_revision_id:rev.value.id,asset_id:assetId}});router.push('/materials/tables?workbook='+r.data.id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function download(id){try{const a=await get('/assets/'+id+'/access');window.open(a.url,'_blank','noopener')}catch(e){error.value=e.message}}
async function completed(result){notice.value={...result,title:confirm.value.title};confirm.value=null;await load()}
async function undo(){try{await api('/documents/'+notice.value.id+(notice.value.archived?'/restore':''),{method:notice.value.archived?'POST':'DELETE',body:{archive_version:notice.value.archive_version,reason:'직전 작업 실행 취소'}});notice.value=null;await load()}catch(e){error.value=e.message}}
function drop(event){dragging.value=false;if(event.dataTransfer.files[0])file.value=event.dataTransfer.files[0]}
</script>
<template><div class="page-heading"><div><div class="section-kicker">자료 관리</div><h1>{{doc?'원본 자료':'자료 가져오기'}}</h1><p class="muted">게시글, 이미지, 엑셀을 가져오면 같은 식품 정보 표로 정리합니다.</p></div><div class="row wrap"><RouterLink v-if="doc" to="/documents" class="secondary">자료함으로</RouterLink><template v-else><RouterLink to="/collection" class="secondary"><RefreshCw :size="16"/> 사이트에서 수집</RouterLink><button v-if="canOperate" class="primary" @click="showUpload=!showUpload"><Plus :size="17"/> 파일 가져오기</button></template></div></div>
<div v-if="notice" class="action-notice" role="status"><span><b>{{notice.title}}</b> {{notice.archived?'삭제했습니다.':'복구했습니다.'}}</span><button class="link" @click="undo">실행 취소</button></div><p v-if="error" class="error" role="alert">{{error}}</p><section v-if="batchResult" class="batch-result" role="status"><div class="row between"><b>{{{archive:'삭제',restore:'복구',purge:'영구 삭제'}[batchResult.action]}} 완료 {{batchResult.succeeded}}개<span v-if="batchResult.failed"> · 처리하지 못한 자료 {{batchResult.failed}}개</span></b><button class="row-action" @click="batchResult=null" aria-label="처리 결과 닫기"><X :size="17"/></button></div><p v-if="batchResult.action==='purge'&&batchResult.succeeded" class="small">자료와 분석 결과를 삭제했습니다. 사용하지 않는 원본 파일도 정리합니다.</p><ul v-if="batchResult.failures.length"><li v-for="f in batchResult.failures" :key="f.id"><b>{{f.title}}</b><span>{{f.message}}</span></li></ul></section>
<template v-if="doc&&rev"><div v-if="doc.archived" class="archive-banner"><Trash2 :size="18"/><div class="grow"><b>삭제한 자료입니다.</b><p>원문과 기존 근거는 보관됩니다. 다시 사용하려면 복구해 주세요.</p></div><button v-if="canOperate" class="secondary" @click="confirm=doc">자료 복구</button></div><section class="panel document-detail"><div class="row between"><StatusBadge :value="doc.analysis_status"/><button v-if="canOperate&&!doc.archived" class="row-action" @click="confirm=doc" aria-label="자료 삭제"><Trash2 :size="18"/></button></div><h2>{{doc.title}}</h2><div class="row wrap small muted"><span>{{new Date(doc.collected_at).toLocaleString('ko-KR')}}</span><span>원문 버전 {{rev.revision_number}}</span><a v-if="doc.source_url" :href="doc.source_url" target="_blank" rel="noopener">사이트 원문 <ArrowUpRight :size="13"/></a></div><div v-if="['incomplete','login_required'].includes(doc.attachment_status)" class="warning">가져오지 못한 첨부가 있습니다. 사이트 연결 상태를 확인한 뒤 다시 수집해 주세요.</div><details class="document-body" :open="!!rev.body_text"><summary>게시글·텍스트 원문</summary><div class="source-text">{{rev.body_text||'텍스트는 원본 파일 또는 추출 결과에서 확인할 수 있습니다.'}}</div></details><div class="asset-list"><div v-for="a in rev.assets" :key="a.id" class="asset-row"><div class="file-type-icon"><FileText :size="21"/></div><div class="grow"><b>{{a.filename}}</b><small>{{Math.round(a.size_bytes/1024)}} KB</small></div><button v-if="!doc.archived&&a.filename.toLowerCase().endsWith('.xlsx')" class="secondary" @click="openTable(a.id)">원본 표 보기</button><button class="row-action" @click="download(a.id)" :aria-label="a.filename+' 다운로드'"><Download :size="18"/></button></div></div><div v-if="!doc.archived" class="document-next-action"><div class="grow"><b>{{doc.analysis_review_ready?'추출 결과가 준비됐습니다.':'자료를 읽고 식품 정보를 정리합니다.'}}</b><p>{{doc.analysis_review_ready?'정리된 표를 원문과 비교하고, 반영할 식품을 선택해 주세요.':'이미지는 OCR로, 텍스트와 표는 각 형식에 맞춰 읽습니다.'}}</p></div><RouterLink v-if="doc.analysis_review_ready" :to="'/analysis-runs/'+doc.latest_analysis_run_id+'/review'" class="primary">추출 결과 검수 <ArrowUpRight :size="16"/></RouterLink><RouterLink v-else-if="doc.latest_analysis_job_id" :to="'/jobs/'+doc.latest_analysis_job_id" class="primary">분석 진행 보기</RouterLink><button v-else-if="canOperate" class="primary" :disabled="busy" @click="analyze"><Play :size="16"/> 분석 시작</button></div><details v-if="!doc.archived&&(canOperate||canReview)" class="advanced-actions"><summary>추가 작업</summary><div class="row wrap"><button v-if="canOperate" class="secondary" :disabled="busy" @click="analyze">다시 분석</button></div></details></section></template>
<template v-else><section v-if="canOperate&&showUpload" class="panel upload-card"><div class="row between"><div><h2>파일 가져오기</h2><p class="muted">자료 등록 후 분석을 시작합니다. 검수 전에는 식품 DB에 반영되지 않습니다.</p></div><button class="row-action" @click="showUpload=false" aria-label="업로드 접기"><X :size="19"/></button></div><label :class="['file-drop',{dragging}]" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop"><Upload :size="28"/><b>{{file?file.name:'파일을 끌어 놓거나 눌러서 선택하세요'}}</b><span>텍스트 · CSV · Excel · PDF · 이미지 / 최대 20MB</span><input type="file" @change="file=$event.target.files[0]" aria-label="파일 선택" accept=".txt,.tsv,.csv,.md,.html,.json,.xlsx,.xls,.pdf,.png,.jpg,.jpeg,.webp"></label><div class="upload-footer"><input v-model="title" placeholder="자료 제목 (선택)" aria-label="문서 제목"><button class="primary" :disabled="busy||!file" @click="upload">{{busy?'가져오는 중…':'등록하고 분석하기'}} <ArrowUpRight :size="16"/></button></div></section><section class="panel document-directory"><div class="directory-toolbar"><div class="segmented" aria-label="자료 목록 구분"><button :class="{active:!archived}" @click="archived=false;load()"><FolderOpen :size="15"/> 전체 자료</button><button :class="{active:archived}" @click="archived=true;load()"><Trash2 :size="15"/> 삭제한 자료</button></div><form class="search-control" @submit.prevent="load()"><Search :size="17"/><input v-model="query" placeholder="자료 제목 검색" aria-label="문서 검색"><button>검색</button></form></div><div class="directory-caption"><span>{{loading?'불러오는 중…':`${data.items.length}개 표시 / 전체 ${data.total??data.items.length}개`}}</span></div><div v-if="canOperate" class="selection-toolbar"><div class="row"><b>{{selectedCount}}개 선택</b><button class="link" :disabled="selecting||loading" @click="selectAllMatches">{{selecting?'선택 중…':'검색 결과 전체 선택'}}</button><button v-if="selectedCount" class="quiet" @click="selectedRows={}">선택 해제</button></div><div class="row wrap"><template v-if="archived"><button class="secondary" :disabled="!selectedCount" @click="batchAction('restore')"><RotateCcw :size="14"/> 선택 복구</button><button class="danger-button" :disabled="!selectedCount" @click="batchAction('purge')"><Trash2 :size="14"/> 선택 영구 삭제</button></template><button v-else class="danger-outline" :disabled="!selectedCount" @click="batchAction('archive')"><Trash2 :size="14"/> 선택 삭제</button></div></div><div class="table-scroll"><table><thead><tr><th v-if="canOperate" class="selection-cell"><input type="checkbox" :checked="allSelected" :indeterminate="someSelected&&!allSelected" @change="togglePage($event.target.checked)" aria-label="현재 페이지 전체 선택"></th><th>자료</th><th>출처</th><th>분석 상태</th><th>가져온 날짜</th><th class="table-actions" :class="{'wide-actions':archived}">관리</th></tr></thead><tbody><tr v-for="d in data.items" :key="d.id" @click="router.push('/documents/'+d.id)" class="clickable" :class="{'selected-row':selectedRows[d.id]}"><td v-if="canOperate" class="selection-cell" @click.stop><input type="checkbox" :checked="!!selectedRows[d.id]" @change="toggleRow(d,$event.target.checked)" :aria-label="d.title+' 선택'"></td><td><div class="document-title-cell"><div class="file-type-icon"><FileText :size="19"/></div><RouterLink :to="'/documents/'+d.id">{{d.title}}</RouterLink></div></td><td class="muted">{{d.board_key||'직접 등록'}}</td><td><StatusBadge :value="d.analysis_status"/></td><td class="muted">{{new Date(d.collected_at).toLocaleDateString('ko-KR')}}</td><td class="table-actions" :class="{'wide-actions':archived}"><button v-if="canOperate&&archived" class="row-action purge-action" :aria-label="d.title+' 영구 삭제'" title="영구 삭제" @click.stop="batchAction('purge',[d])"><Trash2 :size="17"/></button><button v-if="canOperate" class="row-action" :aria-label="d.title+(d.archived?' 복구':' 삭제')" @click.stop="confirm=d"><RotateCcw v-if="d.archived" :size="17"/><Trash2 v-else :size="17"/></button></td></tr></tbody></table></div><div v-if="!data.items.length&&!loading" class="directory-empty"><FolderOpen :size="34"/><h3>{{archived?'삭제한 자료가 없습니다.':'자료함이 비어 있습니다.'}}</h3><p>{{query?'다른 제목으로 검색해 주세요.':archived?'삭제한 자료는 이곳에서 복구할 수 있습니다.':'파일을 가져오거나 사이트에서 새 자료를 수집하세요.'}}</p></div><CursorPager :next="data.next_cursor" @next="load"/></section></template><DocumentBatchDialog v-if="batchConfirm" :items="batchConfirm.items" :action="batchConfirm.action" @close="batchConfirm=null" @done="batchCompleted"/><ArchiveDialog v-if="confirm" :item="confirm" kind="document" @close="confirm=null" @done="completed"/></template>
